import{z as B,x as l,o as s,c as A,q as E,j as n,D as e,d as t,s as u,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Postgres 元组版本与 vacuum","description":"","frontmatter":{"title":"Postgres 元组版本与 vacuum","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pg-vacuum.md","filePath":"cs/pg-vacuum.md","lastUpdated":1791063341000}'),m={name:"cs/pg-vacuum.md"};function p(d,a,c,C,x,D){const o=l("Mermaid");return s(),A("div",null,[a[2]||(a[2]=E('<h1 id="postgres-元组版本与-vacuum" tabindex="-1">Postgres 元组版本与 vacuum <a class="header-anchor" href="#postgres-元组版本与-vacuum" aria-label="Permalink to &quot;Postgres 元组版本与 vacuum&quot;">​</a></h1><div class="epigraph"><p>更新写新堆元组、旧元组打 xmax；vacuum 在所有快照都看不见后回收空间，冻结避免事务 id 回卷。</p><footer>—— 据 PostgreSQL MVCC 文档；Bernstein 多版本；Gray</footer></div><p><a href="/cs/undo-redo-doublewrite">上一课</a>把 InnoDB undo 链与堆版本对照。本课专钉 Postgres：没有 undo 表空间当主路径，行版本就在堆上。主干 <a href="/cs/mvcc">MVCC</a> 已给可见性直觉；进阶要 <strong>vacuum、冻结、膨胀</strong>，否则对照课只停在口号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>插入：新元组 xmin=当前 xid。删除：xmax=当前 xid，行还在。更新：删+插（或 HOT 更新若索引列不变、同页有空）。读者按快照比较 xmin/xmax。缺口是垃圾：死元组占页，索引仍可能指它们直到清理。VACUUM：扫堆，回收死元组，修剪索引，更新冻结 xid，刷新统计（常一起 ANALYZE）。</p><p><span class="marginnote">术语翻译：「死元组」就是已经没人能看见、但还躺在页里的行版本——Postgres 的删除和更新并不立刻腾空间，只是把旧版本打上标记，等 vacuum 来收尸。</span></p><p>长事务/槽位：老快照挡住回收，表膨胀。这是 MVCC GC 课的 Postgres 实例，本课先给机制。</p><p><span class="marginnote">HOT（Heap Only Tuple）减少二级索引维护。冻结把老 xmin 标成永远可见，防 xid 回卷。本课不把 autovacuum 参数表当理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>autovacuum 按死元组比例唤醒。手动 vacuum 锁弱于全表 rewrite。VACUUM FULL 重建表，短锁重。BRIN/可见性映射：全可见页可跳过 vacuum 扫，这是 zone 思想在 GC 上。</p><p>复制：hot_standby 查询在备库持快照，同样可挡主库回收若用反馈。冲突后课。</p><p><span class="marginnote">数字实例：autovacuum 的默认唤醒条件约为「死元组数 &gt; 表行数的 0.2 倍 + 50」。一张 100 万行的表，死元组攒到 20 万零 50 行左右它就动手——不是等表满了才清。</span></p>',12)),(s(),n(i,null,{default:e(()=>[u(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20NEW%5B%22%E6%96%B0%E5%A0%86%E5%85%83%E7%BB%84%22%5D%0A%20%20UPD%20--%3E%20DEAD%5B%22%E6%97%A7%E5%85%83%E7%BB%84%20xmax%22%5D%0A%20%20DEAD%20--%3E%20VAC%5B%22vacuum%20%E5%9B%9E%E6%94%B6%22%5D%0A%20%20SNAP%5B%22%E8%80%81%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20BLOCK%5B%22%E6%8C%A1%E4%BD%8F%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"与 2Q：死空间让扫描读更多页，污染更重。与计划：膨胀后统计若未更新，代价估错。与 WAL：vacuum 写大量 redo，检查点与复制延迟上升。",-1)),(s(),n(i,null,{default:e(()=>[u(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E8%AF%BB%E8%80%85%E6%8C%81%E5%BF%AB%E7%85%A7%20s%20%E8%AF%BB%E4%B8%80%E8%A1%8C%22%5D%20--%3E%20Q1%7B%22xmin%20%E5%9C%A8%20s%20%E5%BC%80%E5%A7%8B%E5%89%8D%E5%B7%B2%E6%8F%90%E4%BA%A4%3F%22%7D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20INV%5B%22%E5%AF%B9%E8%AF%BB%E8%80%85%E4%B8%8D%E5%8F%AF%E8%A7%81%22%5D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20Q2%7B%22xmax%20%E5%B7%B2%E8%AE%BE%E7%BD%AE%E4%B8%94%E5%AF%B9%20s%20%E5%8F%AF%E8%A7%81%3F%22%7D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20VIS%5B%22%E5%8F%AF%E8%A7%81%3A%20%E5%B0%B1%E8%AF%BB%E8%BF%99%E4%B8%80%E7%89%88%22%5D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20INV2%5B%22%E4%B8%8D%E5%8F%AF%E8%A7%81%3A%20%E5%B7%B2%E8%A2%AB%E5%88%A0%E6%88%96%E8%A2%AB%E6%96%B0%E7%89%88%E6%9C%AC%E6%8E%A5%E6%9B%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p>InnoDB 对应 purge undo；名字不同，都是「最小快照之后的版本可丢」。</p><p><span class="marginnote">常见误区：初学者以为 VACUUM FULL 是日常保养——它其实是重锁重建整张表的手术，日常靠普通 autovacuum 维持即可，FULL 只留给膨胀失控后的抢救。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲聚簇回表。也不把 vacuum 当 LSM compaction——相似都是回收，结构不同。xid 回卷是运维事故，机制是冻结。</p><p>后课默认：堆引擎必须持续 vacuum；长快照是膨胀源。聚簇索引与回表：二级索引如何找到聚簇行。</p><p>可见性映射让 vacuum 与扫描跳过全可见页，是跳过索引的 GC 亲戚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Postgres 版本在堆上；vacuum 回收死元组并冻结 xid。</li><li>长快照导致膨胀；HOT 减少索引维护。</li><li>聚簇索引与回表下一课。</li><li>出处：PostgreSQL MVCC；Bernstein；Gray。</li></ul>',8))])}const v=B(m,[["render",p]]);export{h as __pageData,v as default};
